import {all,stage,commit} from './build.mjs';
const non=all.filter(j=>j!=='Stone');
const seven=all.filter(j=>!['Scalia','Thomas'].includes(j));
const audit=(g,final='Historical judgment and ground match; no material revision or historical departure.')=>non.map(j=>({justice:j,provisional:typeof g==='string'?g:g[j],reconciliation:final}));
const common='The four February 26 events are uncoordinated and share a start-of-day baseline including the committed February 25 decisions. None uses another February 26 decision as earlier law.';
export const events=[{
 name:'Franklin v. Gwinnett County Public Schools',page:60,end:78,docket:'No. 90-918',date:'1992-02-26',argued:'December 11, 1991',arguedISO:'1991-12-11',below:'Eleventh Circuit, 911 F.2d 617',file:'Franklin_v_Gwinnett_County_Public_Schools_merits_1992-02-26.md',archive:'micro_IA40385013_0054',event:'The district court dismissed the complaint on the categorical ground that Title IX did not permit damages; the Eleventh Circuit affirmed.',questions:'Whether compensatory damages are available in the recognized Title IX private action for intentional discrimination, and whether the Spending Clause notice principle bars that relief.',baseline:common,
 record:'Franklin seeks reversal and ordinary litigation of her damages claim. She alleges repeated sexual harassment and abuse by teacher/coach Andrew Hill while she attended a federally funded high school, official awareness and failure to act, discouragement of her complaint and closure of the investigation following Hill’s conditional resignation. These are allegations, not judicial findings. She no longer attends the school. The lower court relied on its Title VI precedent Drayden and a Spending Clause limitation; Judge Johnson regarded Drayden as controlling without reaching the additional constitutional characterization. Respondents and the United States defend the damages bar. Backpay and prospective student relief would not redress the pleaded completed injury.',
 entering:'Title IX, 20 U.S.C. §1681(a), prohibits sex discrimination by covered education programs. Cannon v. University of Chicago, 441 U.S. 677, establishes this private action. Bell v. Hood, 327 U.S. 678; Davis v. Passman, 442 U.S. 228; and J. I. Case Co. v. Borak, 377 U.S. 426, distinguish the cognizable action from its appropriate remedies. Guardians Association, 463 U.S. 582, supplies proposition-level support for intentional-discrimination damages, not a single unified opinion. Darrone, 465 U.S. 624, sustains backpay under an analogous statute. Pennhurst, 451 U.S. 1, requires notice of funding conditions. Section 2000d-7, enacted in 1986, refers expressly to remedies at law and in equity; the Restoration Act enacted in 1988 preserves the enforcement setting. Nordic Village’s February 25 federal Treasury-waiver rule does not turn this recipient into the United States or establish State-arm immunity. Hafer’s capacity doctrine is distinct.',
 reach:'The existing cause of action is accepted. Only the categorical remedy bar and the necessary Spending Clause objection are reached. Recipient attribution, proof of intentional violation, causation, damages amount, punitive relief and unintentional effects remain open. The Court need not select among potential constitutional sources of Congress’s Title IX power.',stoneCheck:'The completed February 25 decisions change no defendant, cause, remedy or governing notice premise. Stone joins the opinion’s ordinary-remedy and intentional-condition holdings with their stated limits. His approval permits compensation for proved injury, not punishment, an automatic attribution rule or an award on allegations.',
 action:'The Eleventh Circuit is reversed, 9–0, and the case is remanded for further proceedings on the damages claim.',components:[{title:'Categorical bar to Title IX damages',result:'Reversed and remanded',yes:all,no:[],remedy:'Compensatory relief may be sought for proved intentional discrimination; liability, attribution, causation and amount remain to be adjudicated.'}],opinions:[{form:'Opinion of the Court',author:'White',joins:seven.filter(j=>j!=='White'),relationship:'Supports reversal and remand',scope:'Appropriate-remedies rule and its application to intentional Title IX discrimination, including the Spending Clause objection.'},{form:'Concurrence in the judgment',author:'Scalia',joins:['Thomas'],relationship:'Supports reversal and remand on a narrower statutory ground',scope:'The 1986 remedies enactment acknowledges damages; no automatic full-remedies presumption for all judicially implied causes.'}],assignment:'Stone assigns White from the unanimous reversal coalition; seven Justices join White’s reasoning, and Scalia and Thomas retain their distinct basis.',
 holdings:[{title:'Compensatory relief in the established Title IX action',support:seven,rule:'When a cognizable federal statutory cause of action exists, courts may award appropriate relief absent clear congressional direction limiting it; recognizing that remedy does not create a new cause of action. In Title IX’s established private action, compensatory damages are available for proved intentional discrimination, subject to proof of recipient responsibility, causation and compensable loss.',authority:'White’s opinion, joined by Stone, Blackmun, Stevens, O’Connor, Kennedy and Souter; seven Justices control the remedial rule and application.',explanation:'The Court holds that Title IX does not confine an established private action to remedies incapable of redressing a completed personal injury. Cannon supplies the cause of action; Bell v. Hood and Davis v. Passman distinguish that authority to sue from the appropriate relief a court may grant. Borak confirms that statutory silence about remedy does not itself confine a recognized action to a declaration. Guardians and Darrone support compensatory relief for intentional violations of closely related discrimination statutes. Congress’s 1986 reference to remedies at law and in equity, followed by legislation preserving private enforcement, supplies no direction to bar damages. Recognizing compensation therefore implements the existing action rather than expanding judicial power to hear a new one. Franklin’s departure from school shows why backpay and prospective relief cannot compensate the pleaded past injury. The allegations still require adjudication; the Court awards nothing and decides neither a final recipient-attribution rule nor punitive or unintended-effects liability.',precedents:['*Cannon v. University of Chicago*, 441 U.S. 677 — applied as the established Title IX cause of action; not reopened.','*Bell v. Hood*, 327 U.S. 678 — applied for appropriate remedies in an existing cognizable action, absent a congressional limit.','*Davis v. Passman*, 442 U.S. 228 — applied to separate existence of an action from available relief.','*J. I. Case Co. v. Borak*, 377 U.S. 426 — applied against limiting relief merely because the statute does not enumerate the remedy.','*Guardians Association v. Civil Service Commission*, 463 U.S. 582 — its intentional-discrimination remedial support is applied without inventing a single majority rationale.','*Consolidated Rail Corp. v. Darrone*, 465 U.S. 624 — analogous monetary relief supports the availability of compensation.']},
 {title:'Notice does not bar damages for the pleaded intentional violation',support:seven,rule:'The Spending Clause notice principle does not categorically bar compensatory relief for an intentional violation of Title IX’s express prohibition of sex discrimination within its established private action. Ambiguous funding conditions, unintentional effects and the separate requirements for attributing misconduct to a recipient are not resolved.',authority:'White’s opinion, joined by the same seven Justices, rejects the distinct funding-notice ground offered to sustain dismissal.',explanation:'The Court holds that the asserted lack of notice cannot sustain this categorical damages bar. Pennhurst requires fair notice of conditions imposed on recipients of federal funds; it does not authorize intentional breach of a clear nondiscrimination condition while limiting the injured person to ineffective prospective relief. Title IX expressly forbids sex discrimination, and Cannon supplies the established enforcement action. The pleaded sexual harassment and abuse describe intentional discrimination of the kind addressed by Meritor Savings Bank’s explanation of sex-based harassment, without deciding here when a school is responsible for a teacher’s conduct. Darrone also defeats the premise that a spending-based statute necessarily excludes a monetary award for intentional violations. The objection cannot succeed merely by describing compensation as payment from a recipient’s treasury. This conclusion rests on the enacted condition and existing enforcement law, not a general power to redress every injury. Genuinely ambiguous conditions, proof of institutional responsibility and unintended discriminatory effects remain distinct questions.',precedents:['*Pennhurst State School and Hospital v. Halderman*, 451 U.S. 1 — its funding-condition notice rule is preserved; it does not bar relief for this alleged intentional violation.','*Meritor Savings Bank, FSB v. Vinson*, 477 U.S. 57 — its identification of sex-based harassment informs the pleaded discrimination; no Title VII attribution formula is imported.','*Consolidated Rail Corp. v. Darrone*, 465 U.S. 624 — applied against a categorical objection to monetary remedies under spending legislation.','*Cannon v. University of Chicago*, 441 U.S. 677 — the established action supplies the enforcement premise for the notice analysis.']}],
 law:'Effective February 26, appropriate relief in a cognizable statutory action is not barred by remedial silence alone, and Title IX permits compensation for intentional discrimination. Before this decision, the cause existed but the presented damages bar was unresolved; afterward, that bar and the categorical Spending Clause objection are rejected. No new implied action, punitive remedy, liability for unintended effects, automatic institutional responsibility, or finding against the school is established.',separate:'Scalia, joined by Thomas, agrees that the damages claim may proceed because the 1986 enactment acknowledges legal as well as equitable remedies. They decline to presume every remedy merely from a cause of action that judges previously implied, and do not join the Court’s broader remedial reasoning.',continuity:'Scalia and Thomas, concurrence in judgment, February 26: the 1986 remedies language supports Title IX damages; an implied cause does not automatically carry every remedy, and judicial limits on its remedial scope may be appropriate where Congress has not acknowledged them. Noncontrolling methodology; the Title IX result is shared. No later treatment.',procedure:'Supreme Court review ends with reversal and remand. The damages complaint returns for ordinary proceedings on liability, attribution, causation and compensable loss. No amount is awarded and no prospective school-supervision order is entered.',dependencies:'Later Title IX cases must preserve the difference between remedy availability and recipient liability. Nordic Village remains a distinct federal sovereign-waiver decision.',form:'full',formBasis:'although the judgment is unanimous, Stone joins the controlling remedial and notice reasoning rather than the comparator’s narrower concurrence, changing the proposition coalition from six to seven.',sourceMap:'503 U.S. 63–65 verifies allegations, procedural dismissal, alternate circuit ground and separate opinion below; pages 65–76 supply the remedy and notice authorities and reservations; pages 76–78 verify the narrower concurrence.',audit:audit(Object.fromEntries(non.map(j=>[j,['Scalia','Thomas'].includes(j)?'Reverse under §2000d-7’s enacted acknowledgment of damages; withhold a universal Bell presumption for implied actions.':'Reverse under Cannon, Bell/Davis, Guardians/Darrone and the 1986 enactment; Pennhurst does not bar relief for intentional breach of the express condition.']))),alternatives:'A categorical damages bar relies on remedial silence and caution about implied causes. It fails for the six non-Stone majority proponents because the cause/remedy inquiries differ and ordinary relief remains available; it also fails for Scalia/Thomas because the later enacted acknowledgment independently supplies a narrower route. Notice is separately considered, not assumed from the vote to reverse. Allegations of official awareness are not made into a final attribution rule.',auditFinal:'All nine reverse. Seven join both Court holdings; Scalia/Thomas supply only judgment agreement on their narrower basis. The changed controlling coalition results from Stone’s approved legal ground; no other Justice changes position. No damages category beyond the approved and majority-supported compensatory question is supplied.'
},{
 name:'INDOPCO, Inc. v. Commissioner',page:79,end:90,docket:'No. 90-1278',date:'1992-02-26',argued:'November 12, 1991',arguedISO:'1991-11-12',below:'Third Circuit, 918 F.2d 426',file:'INDOPCO_v_Commissioner_merits_1992-02-26.md',archive:'micro_IA40385013_0081',event:'The taxpayer, formerly National Starch and Chemical Corporation, seeks current deduction of professional acquisition expenses disallowed by the Tax Court and Third Circuit.',questions:'Whether the target’s professional expenses in this friendly acquisition are deductible under §162(a), and whether creation or enhancement of a separate and distinct asset is necessary for capitalization under §263.',baseline:common,
 record:'Unilever’s negotiated acquisition was completed in August 1978. National Starch incurred investment-banking, legal and related expenses to evaluate and accomplish it. Stipulated facts and findings establish enduring corporate benefits from access to Unilever resources and conversion from an independent public corporation to subsidiary status. The taxpayer deducted banking expenses on its return and sought the additional deductions in Tax Court. Commercial propriety and reasonableness of the charges are not disputed. The Commissioner seeks capital classification. A shareholder’s estate-planning preference is not itself treated as a corporate benefit.',
 entering:'IRC §162(a) permits ordinary and necessary current business expenses; §263 denies immediate deduction for capital expenditures. Lincoln Savings, 403 U.S. 345, capitalizes an outlay creating a distinct asset; Welch, 290 U.S. 111, distinguishes current from capital expense; Woodward, 397 U.S. 572, and Hilton Hotels, 397 U.S. 580, address acquisition-related professional costs. Idaho Power, 418 U.S. 1, preserves capitalization over an otherwise available expense category; the taxpayer bears the ordinary burden of demonstrating an authorized deduction. The February 25 Holywell tax-category holdings do not decide this different statutory classification or create a new tax-method rule.',reach:'The legal asset-prerequisite argument and classification on the established transaction record are reached. Hostile acquisitions, failed transactions, unrelated professional fees and a particular amortization period are not decided.',stoneCheck:'The actual transaction, corporate benefits and relevant Code provisions match the approved core. Stone joins capitalization of these expenses and rejection of an exclusive asset prerequisite, preserving the incidental-benefit limitation and all later-cost-recovery questions.',
 action:'The Third Circuit’s judgment denying the immediate deductions is affirmed, 9–0.',components:[{title:'Current deduction of the disputed acquisition expenses',result:'Affirmed',yes:all,no:[],remedy:'Capital classification remains; no new amortization schedule or tax amount is determined.'}],opinions:[{form:'Opinion of the Court',author:'Blackmun',joins:all.filter(j=>j!=='Blackmun'),relationship:'Supports affirmance',scope:'Separate-asset argument, enduring corporate benefits and classification of these transaction expenses.'}],assignment:'Stone assigns Blackmun from the unanimous affirmance coalition.',
 holdings:[{title:'A separate asset is sufficient, but not necessary, for capitalization',support:all,rule:'Creation or enhancement of a separate and distinct asset is a sufficient ground for capitalization under §263, not an indispensable condition; the character, duration and extent of a transaction’s benefits also matter. The professional expenses facilitating this acquisition’s established enduring corporate restructuring benefits are capital expenditures, not immediately deductible §162(a) operating expenses; mere incidental future benefit alone does not compel capitalization.',authority:'Blackmun’s opinion, joined by the other eight Justices; unanimous statutory holding and record application.',explanation:'The Court holds that a sensible business expenditure need not be a current operating expense. Lincoln Savings classified the particular asset-producing payment before it as capital; it did not make creation of a separate asset the only route to capitalization. Welch recognizes that the distinction depends on the expenditure’s character and circumstances, while Woodward and Hilton Hotels connect professional costs to the capital transactions they facilitate. Here the record supports substantial corporate benefits extending beyond 1978: access to Unilever’s resources, simplified ownership and lasting changes in corporate structure. Those benefits belong to the corporation and do not depend solely on a shareholder’s estate-planning preference or an invented profit forecast. The taxpayer’s proposed asset prerequisite would turn a sufficient explanation into an exclusive statutory definition. Its concern about routine expenses is answered by preserving the difference between substantial enduring benefits and incidental future usefulness. The Court affirms only these expenses’ capital classification and determines neither every acquisition’s treatment nor a later recovery period.',precedents:['*Commissioner v. Lincoln Savings & Loan Association*, 403 U.S. 345 — clarified: a separate asset supplies a sufficient capitalization ground, not an exclusive prerequisite.','*Welch v. Helvering*, 290 U.S. 111 — applied for the contextual distinction between necessary business outlays and current expenses.','*Woodward v. Commissioner*, 397 U.S. 572 — applied for the connection between professional expenses and the underlying capital acquisition.','*United States v. Hilton Hotels Corp.*, 397 U.S. 580 — applied for acquisition-related professional costs’ capital character.','*Commissioner v. Idaho Power Co.*, 418 U.S. 1 — preserved: ordinary expense categories do not override required capitalization.','*Interstate Transit Lines v. Commissioner*, 319 U.S. 590 — the taxpayer’s burden to establish an authorized deduction remains unchanged.']}],law:'Effective February 26, the asset-prerequisite contention is rejected and these friendly-acquisition expenses must be capitalized. Lincoln Savings retains full force for its sufficient asset-based category. The §162/§263 distinction, ordinary burden, incidental-benefit qualification and separate rules for later cost recovery remain in force; no automatic capitalization rule for every future benefit or professional fee is created.',separate:'No separate writing was issued.',procedure:'Supreme Court review ends with affirmance. The reviewed denial of immediate deductions remains operative. No remand for a different classification, amortization schedule or additional tax assessment is ordered.',dependencies:'Holywell’s distinct filing obligations remain untouched. Subsequent capitalization questions require their own facts rather than assuming every acquisition expense has these benefits.',form:'compact',formBasis:'unanimous judgment and full opinion, with no material change in rule, coalition, application, remedy or precedent treatment beyond replacing Rehnquist with Stone.',sourceMap:'503 U.S. 80–83 verifies the stipulated transaction, expenses and judgments; pages 83–88 the statutory framework and Lincoln Savings argument; pages 88–90 the corporate benefits and limited classification.',audit:audit('Affirm under §§162/263, Lincoln Savings as a sufficient rather than exclusive category, and Welch/Woodward’s character-of-expenditure analysis; preserve incidental future benefit and later recovery questions.'),alternatives:'The asset-prerequisite path overreads Lincoln Savings because the Court there did not adjudicate every nonasset expenditure. Rejecting that prerequisite could have led to remand if enduring benefits were unsupported, but the stipulated transaction and affirmed findings supply them here. Capital classification does not become a judicially selected amortization period.',auditFinal:'All nine support affirmance and the single combined statutory rule/application. No distinct independently sufficient alternative holding or separate opinion is omitted. No non-Stone departure or material revision.'
},{
 name:'Arkansas v. Oklahoma',page:91,end:114,docket:'No. 90-1262; No. 90-1266 (EPA v. Oklahoma)',date:'1992-02-26',argued:'December 11, 1991',arguedISO:'1991-12-11',below:'Tenth Circuit, 908 F.2d 595',file:'Arkansas_v_Oklahoma_merits_1992-02-26.md',archive:'micro_IA40385013_0080',event:'Both petitions challenge the judgment invalidating EPA’s federal discharge permit for Fayetteville’s sewage-treatment plant.',questions:'Whether EPA may condition this upstream federal permit on downstream state standards; whether existing downstream degradation categorically bars the discharge; and whether EPA’s compliance interpretation and supported technical findings survive judicial review.',baseline:common,
 record:'Fayetteville applied in 1985 for a permit; effluent travels through creeks and the Illinois River for about 39 miles to Oklahoma. The permit includes numerical conditions and modification if a study requires tighter limits for Oklahoma compliance. EPA’s Chief Judicial Officer replaced an undue-impact test with a preponderance showing of no actual detectable violation. The ALJ made component-specific findings meeting that direction, sustained by EPA. Arkansas contests an obligatory downstream rule; EPA defends its authority and actual determination; Oklahoma seeks protection of scenic-water standards. The Tenth Circuit imposed an already-degraded-waters prohibition not advanced by a party, without displacing the no-detectable-violation finding. The separate White River discharge is outside review.',
 entering:'Clean Water Act §§301, 303, 401 and 402 (33 U.S.C. §§1311, 1313, 1341, 1342), including §402(a)(2)’s permit-condition authority; 40 C.F.R. §§122.4(d) and 122.44(d); the relevant Oklahoma standards incorporated in the federal permitting process. Milwaukee II, 451 U.S. 304, displaces federal nuisance common law; Ouellette, 479 U.S. 481, restricts affected-state common-law control without eliminating statutory safeguards. Chevron, 467 U.S. 837, and Seminole Rock, 325 U.S. 410, supply the received agency-interpretation framework. Universal Camera, 340 U.S. 474, requires whole-record substantial-evidence review; State Farm, 463 U.S. 29, governs arbitrary-and-capricious review. The administrative preponderance burden differs from appellate substantial-evidence review. Simulated Lechmere (January 27) preserves deference within controlling statutory precedent; simulated NCIR (December 16) accepts a source-supported regulatory construction; Elias-Zacarias (January 22) rejects substituting a merely permissible factual inference for a supported agency finding under its own statute. None conflicts with the permit scheme. Wyoming’s retained original proceeding concerns a different regulatory limitation.',
 reach:'Both dockets concern the same federal permit. EPA’s authority, the categorical bar, incorporated-standard construction and supported application are reached. A universal statutory duty for every state or federal permit, independent source-state tort remedies, new scientific thresholds and later water conditions are not decided.',stoneCheck:'Lechmere and the February 25 holdings leave the approved statutory delegation and record-review premises intact. Stone joins the actual permit authority and review holdings, changing neither EPA’s proof burden nor numerical conditions. His join does not turn technical expertise into authority or label all small pollution permissible.',
 action:'The Tenth Circuit is reversed unanimously in both dockets. EPA’s reviewed permit determination is sustained under its existing compliance and modification conditions.',components:[{title:'Federal permit, both dockets',result:'Reversed; EPA permit determination sustained',yes:all,no:[],remedy:'Remove the categorical degradation bar; retain the permit’s existing standards, study and modification conditions.'}],opinions:[{form:'Opinion of the Court',author:'Stevens',joins:all.filter(j=>j!=='Stevens'),relationship:'Supports both reversals',scope:'Federal permit authority, no categorical statutory bar, incorporated standards and administrative review.'}],assignment:'Stone assigns Stevens from the unanimous reversal coalition.',
 holdings:[{title:'EPA may require downstream standards in this federal permit',support:all,rule:'The Clean Water Act authorizes EPA, in issuing this federal permit under §402(a), to require compliance with applicable downstream state water-quality standards through its valid regulations. A downstream State’s limited direct role in permitting does not restrict that federal authority; whether the Act itself commands identical compliance in every permitting setting remains open.',authority:'Stevens’s opinion, joined by all other Justices; unanimous statutory-authority holding.',explanation:'The Court holds that EPA acted within Congress’s delegation when it protected Oklahoma’s water standards through the federal permit. Section 402(a)(2) gives the Administrator substantial authority to prescribe permit conditions, and §301(b)(1)(C) identifies attainment of applicable water-quality standards as a statutory objective. Regulation §122.4(d), requiring assurance of affected-state compliance, reasonably carries out that scheme. Milwaukee II identifies the Act’s displacement of federal nuisance law, while Ouellette limits an affected State’s independent common-law and direct permitting role. Neither case bars the federal agency from imposing conditions Congress authorized. Arkansas’s contrary argument confuses limits on a State’s own authority with limits on EPA’s delegated power. Chevron supports this reasonable exercise of that power; expertise alone would not create it. Because the actual federal permit lies within the authorized approach, the Court does not decide whether Congress compels the same formulation in every federal or state permit, or whether an independent source-state remedy applies.',precedents:['*Milwaukee v. Illinois*, 451 U.S. 304 — preserved: the statutory water-pollution scheme displaces federal nuisance common law.','*International Paper Co. v. Ouellette*, 479 U.S. 481 — distinguished: affected-state common-law and direct-input limits do not constrain this delegated EPA condition.','*Chevron U.S.A. Inc. v. Natural Resources Defense Council, Inc.*, 467 U.S. 837 — applied within Congress’s actual delegation; no overhaul of agency deference.','*Lechmere, Inc. v. NLRB*, simulated January 27, 1992 — preserved: deference operates within controlling statutory precedent, and no contrary construction is displaced here.']},
 {title:'Existing degradation is not a categorical statutory prohibition',support:all,rule:'The Clean Water Act does not categorically forbid a new discharge merely because its effluent will reach waters already failing a water-quality standard, irrespective of whether it will cause a detectable violation under the applicable permit standards. Courts may not substitute that categorical prohibition for the Act’s actual permitting and pollution-reduction scheme.',authority:'Stevens’s unanimous opinion rejects the independent statutory basis on which the court of appeals invalidated the permit.',explanation:'The Court holds that the court of appeals added a prohibition Congress did not enact. The Act contains duties directed toward meeting water-quality standards and provisions for reducing existing pollution, including §303(d)’s framework for allocating reduction burdens. It does not say that every additional source must be barred whenever receiving waters already are degraded. Section 402(h), on which the lower court relied, concerns additional pollutants accepted by a treatment plant violating its own permit; it does not create the broader downstream prohibition. Milwaukee II’s recognition of a comprehensive statutory program is not authority to replace that program with a court’s preferred environmental policy. Existing degradation remains relevant when the governing standards make it so, but it does not eliminate the need to evaluate the proposed discharge under those standards. EPA applied the required no-detectable-violation approach here. The Court neither excuses a detectable violation nor decides later permit conditions on facts outside this record.',precedents:['*Milwaukee v. Illinois*, 451 U.S. 304 — its description of a comprehensive program does not authorize an additional judicial categorical ban.']},
 {title:'Reasonable construction of the incorporated downstream standards',support:all,rule:'For this interstate federal permit, EPA’s valid regulation incorporates the applicable, federally approved downstream standards into federal permitting law, and its reasonable, consistently held construction receives substantial deference. EPA permissibly construed Oklahoma’s no-degradation requirement to prohibit an actual detectable or measurable violation, rather than every infinitesimal theoretical effect.',authority:'Stevens’s unanimous opinion controls the interpretation of the standards as used in this federal permit; it does not decide state law for unrelated purposes.',explanation:'The Court holds that the reviewing court must respect EPA’s permissible construction of the standards governing its federal permit. The standards were developed with federal guidance, approved by EPA and incorporated through Regulation §122.4(d); in this interstate permitting setting, they operate as part of federal water-pollution law. Chevron and the received regulatory-deference principle reflected in Seminole Rock support deference to a reasonable, consistently held interpretation within that framework. Requiring a detectable or measurable violation provides a means to determine compliance and does not make every theoretical molecule of additional effluent a downstream veto. NCIR’s source-specific acceptance of a supported regulatory construction is consistent with that approach. The contrary categorical reading lacks support in the statutory or regulatory text. The Court preserves actual standards and their enforcement: it does not announce a general exemption for pollution described as trivial, excuse unreliable science, or confer authority to disregard a demonstrated detectable violation.',precedents:['*Chevron U.S.A. Inc. v. Natural Resources Defense Council, Inc.*, 467 U.S. 837 — applied to the authorized federal permitting construction.','*Bowles v. Seminole Rock & Sand Co.*, 325 U.S. 410 — its received regulatory-interpretation principle remains operative within valid delegated authority.','*INS v. National Center for Immigrants’ Rights, Inc.*, simulated December 16, 1991 — consistent source-specific regulatory construction is applied without importing immigration rules.']},
 {title:'Supported findings govern review of this permit',support:all,rule:'A reviewing court must accept agency adjudicative findings supported by substantial evidence on the record as a whole and may not replace them merely because competing findings also could be supported. Here EPA’s supported finding that Fayetteville carried the administrative preponderance burden of no actual detectable violation sustains the permit; the court’s contrary policy does not establish arbitrary agency action.',authority:'Stevens’s unanimous opinion controls both the appellate-review rule and its application to the reviewed permit.',explanation:'The Court holds that the permit survives review on the record actually decided by EPA. Universal Camera requires substantial evidence supporting the agency’s findings on the whole record, not evidence from which the reviewing court could make different findings. The ALJ addressed nutrient enrichment, appearance, dissolved oxygen and metals under the corrected no-detectable-violation standard and found the city’s preponderance burden satisfied. The identified errors concerning phosphorus in streams and the standards’ edition are harmless here: the findings addressed the more vulnerable lake, and the relevant editions did not materially differ. State Farm requires attention to important aspects of the problem, but the lower court made existing degradation decisive only by adopting its erroneous categorical rule. It could not then label EPA arbitrary for failing to follow that invented rule. The existing study and modification conditions remain safeguards for further information. No new discharge limit, scientific threshold or finding about later water quality is imposed.',precedents:['*Universal Camera Corp. v. NLRB*, 340 U.S. 474 — applied: supported agency findings are not displaced by merely permissible alternative findings.','*Motor Vehicle Manufacturers Association v. State Farm Mutual Automobile Insurance Co.*, 463 U.S. 29 — applied to the actual governing problem, not a court-created categorical policy.']}],
 law:'Effective February 26, the federal permit scheme authorizes the downstream-compliance approach, rejects the categorical already-degraded-waters bar and sustains the supported no-detectable-violation determination. Before this event those precise statutory and permit applications were unresolved; afterward these rules govern at their stated federal-permit scope. EPA’s administrative preponderance burden, whole-record review, valid conditions and modification mechanism remain distinct and unchanged. General deference, state-law remedies and mandatory duties outside this setting are not revised.',separate:'No separate writing was issued.',procedure:'Supreme Court review ends in both dockets. EPA’s permit determination is sustained with its existing compliance, study and modification conditions. No new limit or order concerning the White River discharge is entered; no future scientific finding or Supreme Court supervision is presumed.',dependencies:'Later permit disputes must distinguish statutory authority from a mandatory obligation, and administrative proof from judicial review. The January 22 Wyoming injunction and retained jurisdiction remain separate.',form:'compact',formBasis:'unanimous judgment and full opinion; the same non-Stone positions, controlling rules, permit relief and precedent treatment remain. The paired dockets and four holdings are retained at full substantive depth.',sourceMap:'503 U.S. 94–98 verifies the permit, history, burden and appellate theory; pages 101–108 the statutory text and reserved mandatory-duty issue; pages 109–114 the incorporated standards, two harmless errors, detailed findings and review. The full opinion verifies both dockets and December 11 argument.',audit:audit('Reverse both dockets under §§301/402 and §122.4(d), Ouellette’s distinct common-law scope, Chevron/received regulatory deference and Universal Camera; preserve preponderance proof of no detectable violation and permit conditions.'),alternatives:'Invalidating downstream conditions confuses the State’s limited independent role with EPA’s federal authority. Accepting that authority does not establish a universal congressional command. A categorical degradation ban conflicts with the enacted program; a remand for technical reconsideration lacks a material record defect after the component findings and harmless errors are examined. The two proof standards serve different actors and are never interchanged.',auditFinal:'Both docket judgments and all four operative propositions command nine votes. No scientific finding, new burden or mandatory rule is generated mechanically. The same neutral commitments remain compatible after the Lechmere/NCIR refresh; no material non-Stone revision.'
},{
 name:'Collins v. City of Harker Heights',page:115,end:130,docket:'No. 90-1279',date:'1992-02-26',argued:'November 5, 1991',arguedISO:'1991-11-05',below:'Fifth Circuit, 916 F.2d 284',file:'Collins_v_City_of_Harker_Heights_merits_1992-02-26.md',archive:'micro_IA40385013_0082',event:'The Court reviews dismissal of a widow’s municipal substantive-due-process claim following her husband’s death while working in a sewer.',questions:'Whether §1983 imposes an independent governmental-power-abuse element on public employees, and whether the pleaded deliberate failures to train, warn and equip establish a federal substantive-due-process deprivation.',baseline:common,
 record:'Larry Collins died from asphyxia after entering a manhole to clear a sewer on October 21, 1988. The complaint alleges knowing policies of deficient training, warnings and equipment, a supervisor’s prior loss of consciousness, and intentional failure to comply with the Texas Hazard Communication Act. The city’s alleged knowledge and deliberate omissions are accepted at dismissal. There is no allegation that officials deliberately injured Collins or directed him into a known dangerous sewer. The district court found no constitutional violation; the Fifth Circuit affirmed on an additional governmental-abuse element without deciding that issue. Collins seeks reversal; the city defends both statutory and constitutional grounds.',
 entering:'Section 1983 requires a federal deprivation under color of state law. Monell, 436 U.S. 658, requires municipal policy/custom and causation; Canton, 489 U.S. 378, addresses attribution through deliberately indifferent training, not creation of a substantive right. Daniels, 474 U.S. 327, distinguishes constitutional deprivation from ordinary tort; DeShaney, 489 U.S. 189, rejects a general protection duty while preserving its custody and affirmative-action distinctions; Youngberg, 457 U.S. 307, concerns involuntary custody. Rochin, 342 U.S. 165, identifies constitutionally arbitrary bodily intrusion. Bishop, 426 U.S. 341, and Roth, 408 U.S. 564, distinguish public employment and state entitlements from a general substantive guarantee. The ordinary entering Rule 12(b)(6) pleading framework applies. Hudson’s February 25 narrow beating holding does not make public employment custody. Hafer/Hunter concern individual capacities and defenses, not an automatic municipal defense.',reach:'The properly presented constitutional alternative supports review of dismissal despite rejection of the circuit’s statutory element. Municipal attribution is assumed adequate for purposes of deciding the underlying-right question, not finally established. Procedural due process and an actually pleaded affirmative-danger claim are not decided.',stoneCheck:'Hudson’s limited custodial-force rule does not displace the source-specific approved employer-duty ground. Stone joins Parts A and B below, agrees in the affirming judgment and separately states the approved absence of the necessary custodial or affirmative-deprivation predicate. He does not join Part C’s rational-resource-allocation rationale. The supplement’s expressly stated reservation about affirmative danger is preserved without importing a separate Master file or adopting a new Court doctrine.',
 action:'The Fifth Circuit’s judgment dismissing the federal claim is affirmed, 9–0, on constitutional grounds. Its additional statutory governmental-abuse requirement is rejected.',components:[{title:'Dismissal of the federal substantive-due-process claim',result:'Affirmed',yes:all,no:[],remedy:'No federal damages or supervision order; independent state-law remedies remain for the proper courts.'}],opinions:[{form:'Opinion of the Court, Parts A and B',author:'Stevens',joins:all.filter(j=>j!=='Stevens'),relationship:'Supports affirmance on the stated constitutional limits',scope:'Part A: no extra §1983 governmental-abuse element and separate municipal attribution; Part B: voluntary employment creates no general constitutional safe-workplace duty.'},{form:'Opinion of the Court, Part C',author:'Stevens',joins:all.filter(j=>!['Stevens','Stone'].includes(j)),relationship:'Supplies the Court’s rejection of constitutional arbitrariness',scope:'The pleaded safety omissions, including assumed state-law duties, are not conscience shocking under the limited public-program rationale.'},{form:'Concurrence in part and in the judgment',author:'Stone',joins:[],relationship:'Joins Parts A and B and affirms on his distinct ground concerning the alleged omissions',scope:'Knowledge does not supply custody or a pleaded affirmative deprivation; actual compulsion, deliberately inflicted injury and properly alleged affirmative danger remain open.'}],assignment:'Stone assigns Stevens from the unanimous affirmance coalition. The eight-Justice Part C remains an Opinion of the Court notwithstanding Stone’s withheld join.',
 holdings:[{title:'No extra governmental-abuse element under §1983',support:all,rule:'A municipal employee who establishes deprivation of a federal right under color of state law and municipal responsibility need not also prove an independent, freestanding abuse-of-governmental-power element. The existence of the constitutional wrong and its attribution to municipal policy or custom remain separate required inquiries.',authority:'Part A of Stevens’s opinion, joined by all other Justices; unanimous statutory holding.',explanation:'The Court holds that public employment does not remove the protections Congress made enforceable through §1983. The statute does not distinguish a federal violation by an employer from a federal violation by a government acting in another role. Monell recognizes municipal responsibility for a qualifying policy or custom that causes a federal deprivation, while excluding liability merely because a city employs the wrongdoer. Canton addresses when inadequate training can supply that policy and causal connection; it does not establish a constitutional right whenever training is deficient. An additional abstract governmental-abuse element could defeat otherwise valid speech, equality or bodily-liberty claims solely because the injured person works for government. The circuit’s added requirement therefore cannot sustain dismissal. That error does not establish this plaintiff’s substantive right or require reversal if the actual complaint alleges no constitutional deprivation. The Court assumes attribution only for purposes of deciding that separate question and makes no final municipal-liability finding.',precedents:['*Monell v. Department of Social Services*, 436 U.S. 658 — applied: municipal policy and causation remain distinct from employment alone.','*Canton v. Harris*, 489 U.S. 378 — clarified as an attribution doctrine, not a source of every asserted substantive right.','*Oklahoma City v. Tuttle*, 471 U.S. 808 — preserved for the separation between a constitutional wrong and proof of municipal responsibility.']},
 {title:'Voluntary public employment creates no general constitutional safety duty',support:all,rule:'The substantive Due Process Clause does not impose an independent general obligation on a municipality to provide its voluntary employees a workplace free from unreasonable risks of harm. Accepting public employment does not itself create the custody or deprivation of liberty that supports affirmative constitutional duties of care.',authority:'Part B of Stevens’s opinion, joined by all other Justices; nine Justices adopt this duty limitation.',explanation:'The Court holds that the Constitution does not turn the employment relationship itself into protective custody. DeShaney distinguishes a restriction on the State’s own deprivations from a general guarantee that a person’s interests will not suffer harm. Youngberg’s affirmative care duties arise in involuntary confinement, where the State limits the person’s ability to protect himself; that premise is absent when a person voluntarily accepts municipal employment. Daniels also cautions that substantive due process does not replace ordinary tort duties, and Bishop confirms that the Constitution does not guarantee correct public-employment decisions. The complaint alleges serious risks and knowing failures of protection, but those allegations do not make Collins’s employment a custodial restraint. The contrary approach would constitutionalize a general safe-workplace duty without the necessary constitutional source. This holding does not insulate public employers from applicable federal rights, decide actual compulsion or deliberately inflicted bodily injury, or determine the availability of state safety and tort remedies.',precedents:['*DeShaney v. Winnebago County Department of Social Services*, 489 U.S. 189 — applied to the absence of a general protective duty; distinct custody and affirmative-deprivation questions remain.','*Youngberg v. Romeo*, 457 U.S. 307 — distinguished because voluntary employment is not involuntary custody.','*Daniels v. Williams*, 474 U.S. 327 — preserved: constitutional due process does not replace ordinary tort law; the knowing allegations are not redescribed as mere negligence.','*Bishop v. Wood*, 426 U.S. 341 — applied against treating employment mistakes as a general constitutional violation.']},
 {title:'These pleaded omissions do not establish constitutional arbitrariness',support:non,rule:'The pleaded municipal failures to train, warn and equip sewer workers against known hazards do not constitute arbitrary or conscience-shocking deprivation under substantive due process in this voluntary-employment setting. Even assuming the Texas safety statute creates the asserted duties and a protected liberty interest, breach alone does not establish that distinct substantive constitutional wrong.',authority:'Part C of Stevens’s opinion, joined by White, Blackmun, O’Connor, Scalia, Kennedy, Souter and Thomas; eight Justices control this alternative rejection of the substantive claim. Stone agrees with the judgment on his separately stated ground, without joining this rationale.',explanation:'The Court also holds that the alleged omissions are not constitutionally arbitrary on the theory presented. Rochin’s protection against conscience-shocking government intrusion does not convert every knowing failure of workplace protection into that kind of deprivation. The complaint does not allege deliberate bodily injury or an order knowingly sending Collins into a dangerous sewer. Decisions about training and equipment occur within public programs whose administration ordinarily reflects competing social, political and economic choices. That legal presumption is not a factual finding that this city considered the risks responsibly or that a particular budget justified its conduct. Bishop and Daniels explain why federal substantive due process does not generally replace state employment and tort rules. Even assuming the Texas statute creates the claimed liberty interest, Harrah’s distinction between an entitlement and arbitrary deprivation leaves the same constitutional deficiency. The Court therefore affirms without approving the city’s conduct, adjudicating state remedies or resolving a different claim of affirmative injury.',precedents:['*Rochin v. California*, 342 U.S. 165 — distinguished: the pleaded protective omissions are not its form of conscience-shocking bodily intrusion.','*Bishop v. Wood*, 426 U.S. 341 — applied to preserve the distinction between employment duties and substantive constitutional arbitrariness.','*Daniels v. Williams*, 474 U.S. 327 — applied against substituting substantive due process for ordinary state duties.','*Harrah Independent School District v. Martin*, 440 U.S. 194 — applied to distinguish an assumed state-created interest from constitutionally arbitrary deprivation.']}],
 law:'Effective February 26, §1983 contains no freestanding governmental-abuse element beyond a federal violation and the required municipal responsibility. Voluntary employment creates no general federal safety guarantee; eight Justices also hold these pleaded omissions constitutionally nonarbitrary on Part C’s limited rationale. Monell and Canton remain attribution rules, not sources of the underlying right. No general affirmative-danger doctrine is adopted or categorically rejected, and no knowing allegation is reduced to negligence.',separate:'Stone agrees that the complaint fails because knowledge and deliberate omission do not supply custody or a pleaded affirmative exercise of authority creating the specific danger. He joins the rejection of the circuit’s extra §1983 element and the general safe-workplace claim, but does not rely on a presumption that budget choices justified the omissions. He preserves different claims of actual compulsion, deliberately inflicted injury or properly alleged affirmative danger, without adopting a broader new rule here.',continuity:'Stone, partial concurrence and judgment concurrence, February 26: known risk plus deliberate safety omissions do not supply the required custodial or affirmative-deprivation predicate; no coerced entry, bodily injury, blocked rescue or pleaded affirmative increase in danger exists here. Actual compulsion and properly pleaded affirmative danger remain distinct. This ground and reservation are noncontrolling as a separate writing; it announces no general affirmative-danger test and imports no private Master text. No later treatment.',procedure:'Supreme Court review ends with affirmance of dismissal of the federal claim. No federal compensation or supervision is ordered. Independently available state-law remedies and their procedural treatment remain for the proper courts; their merits and timeliness are not decided.',dependencies:'Hudson remains confined to the established custodial beating. Future municipal claims must independently establish the federal duty and municipal attribution. No state-created-danger test is entered as law.',form:'full',formBasis:'the judgment is unanimous, but Stone withholds the historical whole-opinion join and states a materially distinct constitutional-duty ground; Part C’s controlling rationale has eight votes, while Parts A and B have nine.',sourceMap:'503 U.S. 117–119 verifies the complaint, prior incident and two lower-court grounds; pages 119–124 distinguish statutory liability and municipal attribution; pages 125–130 verify the alleged omissions, constitutional alternatives and assumed state entitlement. No implausible district-court date from the reporter is used as a separate chronology premise.',audit:audit('Affirm under DeShaney/Youngberg’s custody distinction and the actual complaint; reject the additional §1983 element under Monell/Canton. Knowing safety omissions do not create a safe-workplace guarantee or constitute constitutional arbitrariness on these allegations.'),alternatives:'Rejecting the circuit’s extra element does not establish the underlying constitutional right. A general safety guarantee fails the voluntary-employment/custody distinction. A conscience-shocking theory is separately addressed on the allegations, not dismissed merely as negligence. An affirmative-danger route would require acts actually pleaded; compulsion, deliberately inflicted injury or interference with rescue cannot be invented. The state-statute theory still needs a substantive arbitrary deprivation even if its entitlement is assumed.',auditFinal:'Affirmance has nine votes; Parts A/B each have nine; Part C has eight. Stone’s separate ground is not merged with Part C and does not become an affirmative-danger holding. No non-Stone Justice changes judgment, generality or remedy; their constitutional alternatives remain intact.'
}];
stage(events);
if(process.argv.includes('--commit'))commit(events);
